const MIN_MEMBERS = 2
const MAX_MEMBERS = 20
const MAX_GROUP_NAME_LENGTH = 100
const MAX_DESCRIPTION_LENGTH = 200
const CENTS_PER_UNIT = 100
const MAX_AMOUNT_CENTS = 1_000_000 * CENTS_PER_UNIT
