    ['bad-description', () => parseDescription(entry.description)],
    ['bad-payer', () => parseMember(entry.payer, group.members, 'payer')],
    ['bad-amount', () => parseAmount(entry.amount)],
    ['bad-split', () => parseSplit(entry.split, group.members)],
